def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    sep_r = next((r for r in range(h) if len(set(grid[r])) == 1), None)

    if sep_r is not None:
        a, b = grid[:sep_r], grid[sep_r + 1:]
        bg = Counter(x for row in b for x in row).most_common(1)[0][0]
        return [
            [3 if a[r][c] == b[r][c] else bg for c in range(w)]
            for r in range(min(len(a), len(b)))
        ]

    sep_c = next(c for c in range(w)
                 if len({grid[r][c] for r in range(h)}) == 1)
    a = [row[:sep_c] for row in grid]
    b = [row[sep_c + 1:] for row in grid]
    bg = Counter(x for row in b for x in row).most_common(1)[0][0]
    return [
        [3 if a[r][c] == b[r][c] else bg
         for c in range(min(len(a[r]), len(b[r])))]
        for r in range(h)
    ]
